import { FormEvent, ReactNode, useEffect, useState } from "react";
import type { Session } from "@supabase/supabase-js";
import PwaInstall from "./components/PwaInstall";
import FamilyRegistration from "./components/FamilyRegistration";
import AdultRegistration from "./components/AdultRegistration";
import { AnnouncementManager, CompetitionManager, PlanningWorkspace } from "./components/ClubOperations";
import { FamilyAthletes, FamilyHome, GroupManager } from "./components/ClubAdminAndFamily";
import { Shop } from "./components/ProfessionalShop";
import BillingControlCenter from "./components/BillingControlCenter";
import { ensureSupabase, supabase } from "./lib/supabase";
import "./club-app.css";

type Role = "owner" | "admin" | "coach" | "parent" | "adult_athlete" | "minor_athlete";
type Profile = { id: string; email: string; full_name: string | null; phone?: string | null; role: Role };
type Group = { id: string; name: string; category_label: string; colour: string; active: boolean; schedule_days?: string | null; starts_at?: string | null; ends_at?: string | null; season?: string | null };
type Athlete = { id: string; first_name: string; last_name: string; club_status: string; license_status: string; license_number: string | null; training_group_id: string | null; family_id: string | null; user_profile_id: string | null; training_groups?: Group | null };
type Family = { relationship_to_athlete: string; dni_nie: string | null; address_line: string | null; postal_code: string | null; locality: string | null; province: string | null; emergency_phone: string | null; profiles?: Profile | null };
type AthleteRecord = Athlete & { families?: Family | null; health_declarations?: { injury_limitation: string | null; support_needs: string | null; additional_notes: string | null }[]; consents?: { consent_type: string; accepted_at: string }[] };
const famCalendar = "https://www.atletismomadrid.com/calendario";
const roleName: Record<Role, string> = { owner: "Propietario", admin: "Administrador", coach: "Entrenador", parent: "Familia", adult_athlete: "Atleta", minor_athlete: "Atleta menor" };


  export default function App() {
  const [session, setSession] = useState<Session | null>(null);
  const [checking, setChecking] = useState(true);
  const [configured, setConfigured] = useState(Boolean(supabase));
  const [profile, setProfile] = useState<Profile | null>(null);
  const [register, setRegister] = useState<"family" | "adult" | null>(null);
  const invitation = new URLSearchParams(window.location.search).get("invitation");

  useEffect(() => {
    let subscription: { unsubscribe: () => void } | null = null;
    let cancelled = false;

    const start = async () => {
      const client = await ensureSupabase();
      if (cancelled) return;
      if (!client) {
        setChecking(false);
        return;
      }
      setConfigured(true);

      const load = async (next: Session | null) => {
        setSession(next);
        if (next) {
          let { data } = await client.from("profiles").select("*").eq("id", next.user.id).maybeSingle();
          if (!data && next.user.email?.toLowerCase() === "jesusspf@gmail.com") {
            const { error } = await client.rpc("bootstrap_owner");
            if (!error) ({ data } = await client.from("profiles").select("*").eq("id", next.user.id).maybeSingle());
          }
          if (!data) {
            const { error } = await client.rpc("activate_pending_staff_access");
            if (!error) ({ data } = await client.from("profiles").select("*").eq("id", next.user.id).maybeSingle());
          }
          if (!cancelled) setProfile(data as Profile | null);
        } else if (!cancelled) {
          setProfile(null);
        }
        if (!cancelled) setChecking(false);
      };

      client.auth.getSession().then(({ data }) => void load(data.session)).catch(() => {
        if (!cancelled) setChecking(false);
      });
      subscription = client.auth.onAuthStateChange((_event, next) => void load(next)).data.subscription;
    };

    void start();
    return () => {
      cancelled = true;
      subscription?.unsubscribe();
    };
  }, []);

  if (checking) return <main className="secure-screen"><div className="access-box">Comprobando el acceso seguro…</div></main>;
  // Nunca cerramos la web por una comprobación de configuración: el formulario de acceso\n  // sigue disponible y muestra cualquier error real de autenticación al usuario.\n  if (!session) return <Access />;
  if (register === "family") return <FamilyRegistration email={session.user.email ?? ""} onBack={() => { setRegister(null); void supabase?.auth.signOut(); }} />;
  if (register === "adult") return <AdultRegistration email={session.user.email ?? ""} onBack={() => { setRegister(null); void supabase?.auth.signOut(); }} />;
  if (!profile && session.user.email?.toLowerCase() === "jesusspf@gmail.com") {
    return <Portal profile={{ id: session.user.id, email: session.user.email, full_name: "Jesús Pérez", role: "owner" }} signOut={() => void supabase?.auth.signOut()} />;
  }
  if (!profile) return <ChooseRegistration email={session.user.email ?? ""} invitation={invitation} owner={session.user.email?.toLowerCase() === "jesusspf@gmail.com"} family={() => setRegister("family")} adult={() => setRegister("adult")} ownerAction={async () => { if (!supabase) return; const { error } = await supabase.rpc("bootstrap_owner"); if (error) throw error; const { data, error: profileError } = await supabase.from("profiles").select("*").eq("id", session.user.id).single(); if (profileError) throw profileError; setProfile(data as Profile); }} invitationAction={async () => { if (!supabase || !invitation) return; const { error } = await supabase.rpc("accept_staff_invitation", { invitation_token: invitation }); if (error) throw error; const { data } = await supabase.from("profiles").select("*").eq("id", session.user.id).single(); window.history.replaceState({}, "", window.location.pathname); setProfile(data as Profile); }} staffAction={async () => { if (!supabase) return; const { error } = await supabase.rpc("activate_pending_staff_access"); if (error) throw error; const { data, error: profileError } = await supabase.from("profiles").select("*").eq("id", session.user.id).single(); if (profileError) throw profileError; setProfile(data as Profile); }} />;
  return <Portal profile={profile} signOut={() => void supabase?.auth.signOut()} />;
}

function Brand() { const [identity, setIdentity] = useState<{ club_name: string; logo_url: string | null } | null>(null); useEffect(() => { if (!supabase) return; void supabase.from("club_settings").select("club_name,logo_url").eq("id", true).maybeSingle().then(({ data }) => { if (data) setIdentity(data); }); }, []); const words = (identity?.club_name || "Club Atletas de Fuenlabrada").toUpperCase().split(" "); const first = words.slice(0, 2).join(" "); const second = words.slice(2).join(" "); return <div className="portal-brand">{identity?.logo_url ? <img src={identity.logo_url} alt="Escudo del club" /> : <b>AF</b>}<span>{first}<small>{second || "DE FUENLABRADA"}</small></span></div>; }
function LaunchBlocked() { return <main className="secure-screen"><section className="access-box"><Brand /><h1>Acceso aún no abierto</h1><p>El club está terminando la conexión segura. No hay datos de demostración ni inscripción abierta en esta pantalla.</p></section></main>; }
function Access() { const [kind, setKind] = useState<"login" | "signup">("login"); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false); const submit = async (e: FormEvent) => { e.preventDefault(); if (!supabase) return; setBusy(true); const result = kind === "login" ? await supabase.auth.signInWithPassword({ email, password }) : await supabase.auth.signUp({ email, password }); setBusy(false); setMessage(result.error?.message ?? (kind === "signup" ? "Revisa tu correo y confirma la cuenta." : "")); }; return <main className="secure-screen"><section className="access-box"><Brand /><small>ACCESO SEGURO</small><h1>{kind === "login" ? "Entra en tu cuenta" : "Crea tu cuenta"}</h1><p>{kind === "login" ? "Familias, atletas y equipo acceden con su correo y contraseña." : "El registro público es solo para familias y atletas mayores de edad."}</p><form onSubmit={submit}><label>Correo electrónico<input required type="email" value={email} onChange={e => setEmail(e.target.value)} /></label><label>Contraseña<input required minLength={8} type="password" value={password} onChange={e => setPassword(e.target.value)} /></label><button disabled={busy}>{busy ? "Un momento…" : kind === "login" ? "Entrar" : "Crear cuenta"}</button></form>{message && <p className="error-note">{message}</p>}<button className="plain" onClick={() => { setKind(kind === "login" ? "signup" : "login"); setMessage(""); }}>{kind === "login" ? "¿Aún no tienes cuenta? Inicia tu inscripción" : "¿Ya tienes una cuenta? Entrar"}</button><p className="muted">Administradores y entrenadores reciben una invitación personal del club.</p></section></main>; }
function ChooseRegistration({ email, owner, invitation, family, adult, ownerAction, invitationAction, staffAction }: { email: string; owner: boolean; invitation: string | null; family: () => void; adult: () => void; ownerAction: () => Promise<void>; invitationAction: () => Promise<void>; staffAction: () => Promise<void> }) { const [error, setError] = useState(""); const run = async (action: () => Promise<void>, fallback: string) => { try { setError(""); await action(); } catch (e) { setError(e instanceof Error ? e.message : fallback); } }; return <main className="secure-screen"><section className="access-box"><Brand />{owner ? <><small>ACTIVACIÓN INICIAL</small><h1>Activa tu acceso de propietario</h1><p>Esta cuenta será el primer administrador. Después podrás invitar al equipo desde el panel.</p><button onClick={() => void run(ownerAction, "No se pudo activar la administración.")}>Activar mi administración</button>{error && <p className="error-note">{error}</p>}</> : invitation ? <><small>INVITACIÓN DEL CLUB</small><h1>Activa tu acceso</h1><p>La invitación se vinculará a la cuenta {email} y aplicará el rol y grupo asignados por el club.</p><button onClick={() => void run(invitationAction, "No se pudo aceptar la invitación.")}>Aceptar invitación</button>{error && <p className="error-note">{error}</p>}</> : <><small>INSCRIPCIÓN O EQUIPO</small><h1>¿Qué acceso necesitas?</h1><p>Cuenta: {email}</p><button onClick={family}>Soy padre, madre o tutor</button><button className="outline" onClick={adult}>Soy atleta mayor de 18 años</button><button className="plain" onClick={() => void run(staffAction, "No se pudo activar el acceso de equipo.")}>Tengo una invitación como entrenador o administrador</button><p className="muted">Si el correo tiene una invitación activa, se abrirá automáticamente el panel correspondiente.</p>{error && <p className="error-note">{error}</p>}</>}</section></main>; }

function useRows<T>(table: string, select = "*") { const [rows, setRows] = useState<T[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const reload = async () => { if (!supabase) return; setLoading(true); setError(""); const { data, error: queryError } = await supabase.from(table).select(select); setRows((data ?? []) as T[]); setError(queryError?.message ?? ""); setLoading(false); }; useEffect(() => { void reload(); }, [table, select]); return { rows, loading, error, reload }; }
function Header({ title, text, children }: { title: string; text: string; children?: ReactNode }) { return <div className="page-head"><div><h1>{title}</h1><p>{text}</p></div>{children}</div>; }
function Empty({ children }: { children: ReactNode }) { return <div className="empty">{children}</div>; }
function Portal({ profile, signOut }: { profile: Profile; signOut: () => void }) { const [section, setSection] = useState("Inicio"); const [focusedAthleteId, setFocusedAthleteId] = useState(""); const menu = profile.role === "coach" ? ["Inicio", "Mi grupo", "Planificación", "Asistencia", "Carreras", "Avisos", "Tienda"] : ["owner", "admin"].includes(profile.role) ? ["Inicio", "Atletas", "Grupos", "Cuotas", "Carreras", "Asistencia", "Avisos", "Invitaciones", "Tienda", "Configuración"] : ["Inicio", profile.role === "parent" ? "Mis atletas" : "Mi perfil", "Carreras", "Cuotas", "Avisos", "Tienda"];
  const notices = useRows<{ id: string; created_by: string }>("announcements", "id,created_by"); const deliveries = useRows<{ announcement_id: string; recipient_profile_id: string }>("announcement_deliveries", "announcement_id,recipient_profile_id"); const reads = useRows<{ announcement_id: string; profile_id: string }>("announcement_reads", "announcement_id,profile_id"); const mine = new Set(deliveries.rows.filter(item => item.recipient_profile_id === profile.id).map(item => item.announcement_id)); const inbox = notices.rows.filter(item => item.created_by !== profile.id && mine.has(item.id)).map(item => item.id); const unread = inbox.filter(id => !reads.rows.some(read => read.announcement_id === id && read.profile_id === profile.id)).length;
  useEffect(() => { const timer = window.setInterval(() => { void notices.reload(); void deliveries.reload(); void reads.reload(); }, 15000); return () => window.clearInterval(timer); }, []);
  const openAthlete = (id: string) => { setFocusedAthleteId(id); setSection("Mis atletas"); };
  return <main className="club-shell"><aside className="club-side"><Brand /><small className="side-role">{roleName[profile.role]}</small><nav>{menu.map(item => <button className={section === item ? "selected" : ""} key={item} onClick={() => setSection(item)}>{item}{item === "Avisos" && unread > 0 && <b className="notice-count">{unread > 99 ? "99+" : unread}</b>}</button>)}</nav><div className="side-user"><b>{profile.full_name || profile.email}</b><small>{roleName[profile.role]}</small><button className="plain" onClick={signOut}>Cerrar sesión</button></div></aside><section className="club-content"><header className="topbar"><span>Club Atletas de Fuenlabrada</span><PwaInstall /></header>{["owner", "admin"].includes(profile.role) ? <Admin section={section} profile={profile} go={setSection} /> : profile.role === "coach" ? <Coach section={section} profile={profile} /> : <Member section={section} profile={profile} go={setSection} openAthlete={openAthlete} focusedAthleteId={focusedAthleteId} />}</section></main>; }

function Admin({ section, profile, go }: { section: string; profile: Profile; go: (section: string) => void }) {
  if (section === "Atletas") return <AthletesAdmin />;
  if (section === "Grupos") return <GroupManager />;
  if (section === "Invitaciones") return <Invitations />;
  if (section === "Cuotas") return <Fees profile={profile} />;
  if (section === "Tienda") return <Shop profile={profile} />;
  if (section === "Carreras") return <CompetitionManager profile={profile} manager />;
  if (section === "Asistencia") return <Attendance profile={profile} />;
  if (section === "Avisos") return <AnnouncementManager profile={profile} />;
  if (section === "Configuración") return <Settings />;
  return <AdminHome profile={profile} go={go} />;
}
function AdminHome({ profile, go }: { profile: Profile; go: (section: string) => void }) {
  const athletes = useRows<Athlete>("athletes", "id,first_name,last_name,club_status");
  const groups = useRows<Group>("training_groups");
  const orders = useRows<{ id: string; status: string; total_cents: number; created_at: string }>("club_orders", "id,status,total_cents,created_at");
  const ledger = useRows<{ id: string; status: string; amount_cents: number }>("payment_ledger", "id,status,amount_cents");
  const pendingRows = athletes.rows.filter(a => a.club_status === "pending_review");
  const pendingOrders = orders.rows.filter(order => !["paid", "cancelled"].includes(order.status));
  const queryError = athletes.error || groups.error || orders.error || ledger.error;
  return <><Header title={`Buenos días, ${profile.full_name?.split(" ")[0] || "Jesús"}`} text="Resumen real del club." />
    {queryError && <p className="error-note panel">No se pudieron consultar los datos: {queryError}</p>}
    <section className="metric-grid"><Metric label="Atletas registrados" value={`${athletes.rows.length}`} onClick={() => go("Atletas")} /><Metric label="Altas en revisión" value={`${pendingRows.length}`} onClick={() => go("Atletas")} /><Metric label="Grupos activos" value={`${groups.rows.filter(g => g.active).length}`} onClick={() => go("Grupos")} /><Metric label="Pedidos pendientes" value={`${pendingOrders.length}`} onClick={() => go("Tienda")} /></section>
    <section className="two-columns"><article className="panel actionable-panel" onClick={() => go("Atletas")}><h2>Altas pendientes <span>Ver atletas →</span></h2>{pendingRows.length ? pendingRows.map(a => <p key={a.id}>{a.first_name} {a.last_name}</p>) : <Empty>{athletes.loading ? "Consultando solicitudes…" : "No hay solicitudes pendientes."}</Empty>}</article><article className="panel actionable-panel" onClick={() => go("Tienda")}><h2>Pedidos y cobros <span>Gestionar →</span></h2><p><b>{pendingOrders.length}</b> pedido(s) por preparar o cobrar.</p><p><b>{ledger.rows.filter(item => ["draft", "awaiting_admin", "approved"].includes(item.status)).length}</b> cobro(s) pendiente(s) de revisar.</p></article></section>
    <section className="quick-actions panel"><h2>Acciones rápidas</h2><button onClick={() => go("Atletas")}>Revisar atletas</button><button onClick={() => go("Grupos")}>Gestionar grupos</button><button onClick={() => go("Asistencia")}>Ver asistencia en directo</button><button onClick={() => go("Invitaciones")}>Invitar entrenador</button><button onClick={() => go("Configuración")}>Configurar el club</button></section>
  </>;
}
function Metric({ label, value, onClick }: { label: string; value: string; onClick?: () => void }) { return <button className={`metric ${onClick ? "metric-action" : ""}`} onClick={onClick}><small>{label}</small><b>{value}</b><em>Ver →</em></button>; }
function AthletesAdmin() {
  const { rows, loading, error, reload } = useRows<AthleteRecord>("athletes", "*,training_groups(*),families(*,profiles(*)),health_declarations(*),consents(*)");
  const groups = useRows<Group>("training_groups");
  const [selectedId, setSelectedId] = useState(""); const [changing, setChanging] = useState(""); const [message, setMessage] = useState("");
  const selected = rows.find(a => a.id === selectedId) || null;
  const [groupId, setGroupId] = useState(""); const [status, setStatus] = useState(""); const [licenseStatus, setLicenseStatus] = useState(""); const [licenseNumber, setLicenseNumber] = useState("");
  useEffect(() => { if (selected) { setGroupId(selected.training_group_id || ""); setStatus(selected.club_status); setLicenseStatus(selected.license_status); setLicenseNumber(selected.license_number || ""); setMessage(""); } }, [selectedId]);
  const save = async () => { if (!selected || !supabase) return; setChanging(selected.id); setMessage(""); const { error: saveError } = await supabase.from("athletes").update({ training_group_id: groupId || null, club_status: status, license_status: licenseStatus, license_number: licenseNumber || null }).eq("id", selected.id); setChanging(""); if (saveError) return setMessage(saveError.message); setMessage("Ficha actualizada."); void reload(); };
  const consentNames: Record<string, string> = { privacy: "Privacidad", health_data: "Datos de salud", image_use: "Uso de imagen", fam_data: "Datos FAM", club_rules: "Normativa del club", recurring_payment: "Pago recurrente" };
  return <><Header title="Atletas" text="Pulsa un atleta para abrir su ficha completa y gestionar su alta, grupo y licencia." />{error && <p className="error-note panel">No se pudieron consultar las solicitudes: {error}</p>}<div className="panel table">{loading ? "Cargando…" : rows.map(a => <button className={`row athlete-row ${selectedId === a.id ? "selected-row" : ""}`} key={a.id} onClick={() => setSelectedId(a.id)}><span><b>{a.first_name} {a.last_name}</b><small>{a.training_groups?.name || "Sin grupo"}</small></span><span>{a.club_status === "pending_review" ? "En revisión" : a.club_status === "active" ? "Activo" : a.club_status}</span><span>Licencia: {a.license_status === "active" ? a.license_number || "activa" : "pendiente"}</span><span>Ver ficha →</span></button>)}{!loading && !rows.length && !error && <Empty>Aún no hay atletas registrados.</Empty>}</div>{selected && <section className="athlete-detail"><Header title={`${selected.first_name} ${selected.last_name}`} text="Expediente del atleta y datos declarados durante la inscripción."><button className="outline" onClick={() => setSelectedId("")}>Cerrar ficha</button></Header><div className="detail-grid"><article className="panel"><h2>Padre, madre o tutor</h2><p><b>{selected.families?.profiles?.full_name || "Sin tutor asociado"}</b></p><p>{selected.families?.profiles?.email || "Correo no disponible"}</p><p>Teléfono: {selected.families?.profiles?.phone || "No indicado"}</p><p>Teléfono de emergencia: {selected.families?.emergency_phone || "No indicado"}</p><p>Relación: {selected.families?.relationship_to_athlete || "No indicada"}</p></article><article className="panel"><h2>Datos de contacto</h2><p>{selected.families?.address_line || "Dirección no indicada"}</p><p>{[selected.families?.postal_code, selected.families?.locality, selected.families?.province].filter(Boolean).join(" · ") || "Localidad no indicada"}</p><p>DNI/NIE del tutor: {selected.families?.dni_nie || "No indicado"}</p></article><article className="panel"><h2>Salud y consentimientos</h2><p>Lesiones: {selected.health_declarations?.[0]?.injury_limitation || "No declaradas"}</p><p>Necesidades: {selected.health_declarations?.[0]?.support_needs || "No declaradas"}</p><small>{selected.consents?.length ? selected.consents.map(c => consentNames[c.consent_type] || c.consent_type).join(" · ") : "Sin consentimientos registrados"}</small></article><article className="panel"><h2>Gestión deportiva</h2><label>Estado de alta<select value={status} onChange={e => setStatus(e.target.value)}><option value="pending_review">En revisión</option><option value="active">Activo</option><option value="rejected">Rechazado</option></select></label><label>Grupo<select value={groupId} onChange={e => setGroupId(e.target.value)}><option value="">Sin grupo</option>{groups.rows.filter(g => g.active).map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select></label><label>Licencia<select value={licenseStatus} onChange={e => setLicenseStatus(e.target.value)}><option value="pending">Pendiente</option><option value="active">Activa</option><option value="rejected">Rechazada</option></select></label><label>Número de licencia<input value={licenseNumber} onChange={e => setLicenseNumber(e.target.value)} placeholder="Ej. M-12345" /></label><button disabled={changing === selected.id} onClick={() => void save()}>{changing === selected.id ? "Guardando…" : "Guardar cambios"}</button>{message && <p className={message === "Ficha actualizada." ? "success-note" : "error-note"}>{message}</p>}</article></div></section>}</>; }
function Groups({ profile }: { profile: Profile }) {
  const { rows, reload } = useRows<Group>("training_groups");
  const coaches = useRows<Profile>("profiles", "id,email,full_name,role");
  const assignments = useRows<{ training_group_id: string; coach_profile_id: string }>("training_group_coaches");
  const [selectedId, setSelectedId] = useState(""); const [notice, setNotice] = useState(""); const [saving, setSaving] = useState(false);
  const blank = { name: "", category_label: "", colour: "#2563eb", schedule_days: "", starts_at: "", ends_at: "", season: "2026", active: true };
  const [form, setForm] = useState(blank); const [coachIds, setCoachIds] = useState<string[]>([]);
  const selected = rows.find(row => row.id === selectedId);
  useEffect(() => { if (!selected) return; setForm({ name: selected.name, category_label: selected.category_label, colour: selected.colour, schedule_days: selected.schedule_days || "", starts_at: selected.starts_at?.slice(0, 5) || "", ends_at: selected.ends_at?.slice(0, 5) || "", season: selected.season || "2026", active: selected.active }); setCoachIds(assignments.rows.filter(item => item.training_group_id === selected.id).map(item => item.coach_profile_id)); setNotice(""); }, [selectedId, rows.length, assignments.rows.length]);
  const startNew = () => { setSelectedId(""); setForm(blank); setCoachIds([]); setNotice(""); };
  const save = async (e: FormEvent) => { e.preventDefault(); if (!supabase) return; setSaving(true); setNotice(""); const payload = { ...form, starts_at: form.starts_at || null, ends_at: form.ends_at || null, schedule_days: form.schedule_days || null }; const result = selectedId ? await supabase.from("training_groups").update(payload).eq("id", selectedId).select("id").single() : await supabase.from("training_groups").insert(payload).select("id").single(); if (result.error || !result.data) { setSaving(false); return setNotice(result.error?.message || "No se pudo guardar el grupo."); } const groupId = result.data.id; const { error: removeError } = await supabase.from("training_group_coaches").delete().eq("training_group_id", groupId); if (removeError) { setSaving(false); return setNotice(removeError.message); } if (coachIds.length) { const { error: assignError } = await supabase.from("training_group_coaches").insert(coachIds.map(coach_profile_id => ({ training_group_id: groupId, coach_profile_id }))); if (assignError) { setSaving(false); return setNotice(assignError.message); } } setSelectedId(groupId); setSaving(false); setNotice("Grupo y entrenadores guardados."); void reload(); void assignments.reload(); };
  const coachesOnly = coaches.rows.filter(person => person.role === "coach");
  return <><Header title="Grupos" text="Pulsa un grupo para ver su ficha, editar el horario y asignar entrenadores."><button onClick={startNew}>Nuevo grupo</button></Header><div className="cards">{rows.map(g => <button className={`panel group-card group-button ${selectedId === g.id ? "selected-row" : ""}`} key={g.id} onClick={() => setSelectedId(g.id)}><i style={{ background: g.colour }} /><h2>{g.name}</h2><p>{g.category_label}</p><small>{g.schedule_days ? `${g.schedule_days} · ${g.starts_at?.slice(0, 5)}–${g.ends_at?.slice(0, 5)}` : "Horario pendiente"}</small><small>{assignments.rows.filter(item => item.training_group_id === g.id).length} entrenador(es) asignado(s)</small></button>)}{!rows.length && <Empty>Aún no hay grupos creados.</Empty>}</div><form className="panel group-editor" onSubmit={save}><h2>{selected ? `Ficha del grupo: ${selected.name}` : "Nuevo grupo"}</h2><div className="ops-grid"><label>Nombre<input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Sub 14" /></label><label>Categoría<input required value={form.category_label} onChange={e => setForm({ ...form, category_label: e.target.value })} placeholder="Sub 14" /></label><label>Días de entrenamiento<input value={form.schedule_days} onChange={e => setForm({ ...form, schedule_days: e.target.value })} placeholder="Lunes a jueves" /></label><label>Hora de inicio<input type="time" value={form.starts_at} onChange={e => setForm({ ...form, starts_at: e.target.value })} /></label><label>Hora de final<input type="time" value={form.ends_at} onChange={e => setForm({ ...form, ends_at: e.target.value })} /></label><label>Temporada<input value={form.season} onChange={e => setForm({ ...form, season: e.target.value })} placeholder="2026" /></label><label>Color<input type="color" value={form.colour} onChange={e => setForm({ ...form, colour: e.target.value })} /></label><label className="check-line"><input type="checkbox" checked={form.active} onChange={e => setForm({ ...form, active: e.target.checked })} />Grupo activo</label></div><fieldset className="coach-picker"><legend>Entrenadores asignados</legend>{coachesOnly.length ? coachesOnly.map(person => <label key={person.id}><input type="checkbox" checked={coachIds.includes(person.id)} onChange={e => setCoachIds(e.target.checked ? [...coachIds, person.id] : coachIds.filter(id => id !== person.id))} />{person.full_name || person.email} <small>{person.email}</small></label>) : <p className="muted">Todavía no hay entrenadores con cuenta. Créales primero una invitación desde «Invitaciones».</p>}</fieldset><button disabled={saving}>{saving ? "Guardando…" : "Guardar grupo y entrenadores"}</button>{notice && <p className={notice.startsWith("Grupo") ? "success-note" : "error-note"}>{notice}</p>}</form></>;
}
function Invitations() { const groups = useRows<Group>("training_groups"); const links = useRows<{ id: string; email: string | null; role: string; expires_at: string; accepted_at: string | null }>("invitation_links"); const [email, setEmail] = useState(""); const [role, setRole] = useState<"admin" | "coach">("coach"); const [group, setGroup] = useState(""); const [link, setLink] = useState(""); const [error, setError] = useState(""); const submit = async (e: FormEvent) => { e.preventDefault(); setError(""); const { data, error: rpcError } = await supabase!.rpc("create_staff_invitation", { target_email: email, target_role: role, target_group_id: role === "coach" && group ? group : null }); if (rpcError) return setError(rpcError.message); setLink(`${window.location.origin}/?invitation=${(data as { token: string }).token}`); setEmail(""); void links.reload(); }; return <><Header title="Invitaciones" text="Accesos restringidos para administradores y entrenadores." /><form className="panel invite-form" onSubmit={submit}><label>Correo<input type="email" required value={email} onChange={e => setEmail(e.target.value)} /></label><label>Rol<select value={role} onChange={e => setRole(e.target.value as "admin" | "coach")}><option value="coach">Entrenador</option><option value="admin">Administrador</option></select></label>{role === "coach" && <label>Grupo<select value={group} onChange={e => setGroup(e.target.value)}><option value="">Asignar más tarde</option>{groups.rows.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select></label>}<button>Crear enlace personal</button>{error && <p className="error-note">{error}</p>}</form>{link && <article className="panel"><h2>Enlace creado</h2><p className="link-box">{link}</p><button onClick={() => void navigator.clipboard.writeText(link)}>Copiar para correo o WhatsApp</button><small>Caduca en 14 días.</small></article>}<article className="panel table">{links.rows.map(i => <div className="row" key={i.id}><span><b>{i.email || "Enlace sin correo"}</b><small>{i.role}</small></span><span>{i.accepted_at ? "Aceptada" : "Pendiente"}</span><span>Caduca {new Date(i.expires_at).toLocaleDateString("es-ES")}</span></div>)}{!links.rows.length && <Empty>No hay invitaciones creadas.</Empty>}</article></>; }
function Fees({ profile }: { profile: Profile }) {
  const manager = ["owner", "admin"].includes(profile.role);
  const ledger = useRows<{ id: string; description: string; amount_cents: number; status: string; scheduled_for: string | null }>("payment_ledger");
  const [cardBusy, setCardBusy] = useState(false);
  const [cardMessage, setCardMessage] = useState("");

  const configureCard = async () => {
    const client = supabase;
    if (!client) {
      setCardMessage("No se pudo iniciar el pago seguro. Inténtalo de nuevo.");
      return;
    }
    setCardBusy(true);
    setCardMessage("");
    try {
      const { data } = await client.auth.getSession();
      const response = await fetch("/api/create-payment-method-setup", {
        method: "POST",
        headers: {
          "content-type": "application/json",
          authorization: `Bearer ${data.session?.access_token || ""}`,
        },
        body: "{}",
      });
      const body = await response.json().catch(() => ({})) as { url?: string; error?: string };
      if (!response.ok || !body.url) throw new Error(body.error || "No se pudo abrir Stripe.");
      window.location.assign(body.url);
    } catch (error) {
      setCardMessage(error instanceof Error ? error.message : "No se pudo abrir Stripe. Inténtalo de nuevo.");
      setCardBusy(false);
    }
  };

  if (manager) return <BillingControlCenter />;

  return <><Header title="Cuotas y cobros" text="Consulta tus próximos cobros y su estado." /><section className="two-columns"><article className="panel"><small>STRIPE · PAGO SEGURO</small><h2>Tu método de pago</h2><p>La tarjeta se añade o actualiza directamente en Stripe. El club no almacena números de tarjeta ni CVV.</p><button disabled={cardBusy} onClick={() => void configureCard()}>{cardBusy ? "Abriendo Stripe…" : "Añadir o cambiar tarjeta"}</button>{cardMessage && <p className="error-note">{cardMessage}</p>}</article><article className="panel"><h2>Pagos seguros</h2><p>El club revisa y aprueba cada cuota antes de preparar el pago.</p><p>Una vez aprobado, el cobro se asocia a tu cuenta y aparece en esta lista.</p></article></section><article className="panel table">{ledger.rows.map(item => <div className="row" key={item.id}><span><b>{item.description}</b><small>{item.scheduled_for || "Sin fecha"}</small></span><span>{(item.amount_cents / 100).toFixed(2)} €</span><span>{item.status}</span></div>)}{!ledger.rows.length && <Empty>No hay cobros creados aún.</Empty>}</article></>;
}

function useCoachGroups() { return useRows<any>("training_group_coaches", "training_groups(*)"); }
function Coach({ section, profile }: { section: string; profile: Profile }) { if (section === "Mi grupo") return <CoachGroups />; if (section === "Planificación") return <PlanningWorkspace profile={profile} />; if (section === "Asistencia") return <Attendance profile={profile} />; if (section === "Carreras") return <CompetitionManager profile={profile} />; if (section === "Avisos") return <AnnouncementManager profile={profile} />; const assigned = useCoachGroups(); const groups = assigned.rows.map(item => item.training_groups).filter(Boolean) as Group[]; return <><Header title={`Hola, ${profile.full_name?.split(" ")[0] || "entrenador"}`} text="Tus grupos, planificación y asistencia." /><div className="cards">{groups.map(g => <article className="panel group-card" key={g.id}><i style={{ background: g.colour }} /><h2>{g.name}</h2><p>{g.category_label}</p><small>Acceso limitado a este grupo</small></article>)}{!assigned.loading && !groups.length && <Empty>No tienes grupos asignados. Un administrador debe asignarte uno.</Empty>}</div></>; }
function CoachGroups() { const assigned = useCoachGroups(); const ids = assigned.rows.map(item => item.training_groups?.id).filter(Boolean); const athletes = useRows<Athlete>("athletes", "*,training_groups(*)"); const mine = athletes.rows.filter(a => ids.includes(a.training_group_id)); return <><Header title="Mi grupo" text="Atletas de los grupos que tienes asignados." /><article className="panel table">{mine.map(a => <div className="row" key={a.id}><span><b>{a.first_name} {a.last_name}</b><small>{a.training_groups?.name}</small></span><span>Licencia: {a.license_status === "active" ? a.license_number || "activa" : "pendiente"}</span><span>{a.club_status}</span></div>)}{!mine.length && <Empty>No hay atletas visibles en tus grupos.</Empty>}</article></>; }
function Plans({ profile }: { profile: Profile }) { const assigned = useCoachGroups(); const groups = assigned.rows.map(item => item.training_groups).filter(Boolean) as Group[]; const plans = useRows<{ id: string; title: string; body: string; week_starts_on: string; training_group_id: string }>("training_plans"); const [form, setForm] = useState({ group: "", title: "", body: "", week: new Date().toISOString().slice(0, 10) }); const [error, setError] = useState(""); const save = async (e: FormEvent) => { e.preventDefault(); const { error: insertError } = await supabase!.from("training_plans").upsert({ training_group_id: form.group, title: form.title, body: form.body, week_starts_on: form.week, published_at: new Date().toISOString(), created_by: profile.id }, { onConflict: "training_group_id,week_starts_on" }); if (insertError) return setError(insertError.message); setForm({ group: "", title: "", body: "", week: new Date().toISOString().slice(0, 10) }); void plans.reload(); }; return <><Header title="Planificación" text="Publica el plan semanal de tus grupos. La marca de agua se incluirá al compartir." /><form className="panel stacked-form" onSubmit={save}><label>Grupo<select required value={form.group} onChange={e => setForm({ ...form, group: e.target.value })}><option value="">Selecciona un grupo</option>{groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select></label><label>Título<input required value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></label><label>Inicio de semana<input required type="date" value={form.week} onChange={e => setForm({ ...form, week: e.target.value })} /></label><label>Plan<textarea required value={form.body} onChange={e => setForm({ ...form, body: e.target.value })} /></label><button>Publicar planificación</button>{error && <p className="error-note">{error}</p>}</form><div className="cards">{plans.rows.filter(p => groups.some(g => g.id === p.training_group_id)).map(p => <article className="panel plan" key={p.id}><small>CLUB ATLETAS DE FUENLABRADA · USO INTERNO</small><h2>{p.title}</h2><p>{p.body}</p><button onClick={() => void navigator.share?.({ title: p.title, text: `${p.title}\n\n${p.body}\n\nCLUB ATLETAS DE FUENLABRADA · USO INTERNO` })}>Compartir plan</button></article>)}</div></>; }
function Attendance({ profile }: { profile: Profile }) {
  const allGroups = useRows<Group>("training_groups"); const assigned = useCoachGroups(); const athletes = useRows<Athlete>("athletes", "*,training_groups(*)"); const sessions = useRows<{ id: string; training_group_id: string; starts_at: string }>("attendance_sessions"); const records = useRows<{ id: string; session_id: string; athlete_id: string; attended: boolean | null }>("attendance_records");
  const groups = ["owner", "admin"].includes(profile.role) ? allGroups.rows : assigned.rows.map(item => item.training_groups).filter(Boolean) as Group[];
  const [groupId, setGroupId] = useState(""); const [when, setWhen] = useState(new Date().toISOString().slice(0, 16)); const [selectedSession, setSelectedSession] = useState(""); const [busy, setBusy] = useState(""); const [error, setError] = useState("");
  useEffect(() => { const timer = window.setInterval(() => { void sessions.reload(); void records.reload(); void athletes.reload(); }, 10000); return () => window.clearInterval(timer); }, []);
  const visibleSessions = sessions.rows.filter(s => !groupId || s.training_group_id === groupId); const activeSession = selectedSession || visibleSessions[0]?.id || ""; const session = sessions.rows.find(s => s.id === activeSession); const roster = athletes.rows.filter(a => a.training_group_id === (session?.training_group_id || groupId));
  const now = Date.now(); const activeSessions = sessions.rows.filter(item => { const moment = new Date(item.starts_at).getTime(); return moment <= now + 30 * 60 * 1000 && moment >= now - 2 * 60 * 60 * 1000; }).sort((a, b) => new Date(a.starts_at).getTime() - new Date(b.starts_at).getTime());
  const createSession = async (e: FormEvent) => { e.preventDefault(); setError(""); if (!groupId) return setError("Selecciona un grupo."); const { data, error: createError } = await supabase!.from("attendance_sessions").insert({ training_group_id: groupId, starts_at: new Date(when).toISOString(), created_by: profile.id }).select("id").single(); if (createError) return setError(createError.message); setSelectedSession(data.id); void sessions.reload(); };
  const mark = async (athleteId: string, attended: boolean) => { if (!activeSession) return; setBusy(athleteId); const { error: markError } = await supabase!.from("attendance_records").upsert({ session_id: activeSession, athlete_id: athleteId, attended, marked_by: profile.id, marked_at: new Date().toISOString() }, { onConflict: "session_id,athlete_id" }); if (!markError) { const { error: notificationError } = await supabase!.rpc("queue_attendance_notification", { target_session_id: activeSession, target_athlete_id: athleteId, did_attend: attended }); if (notificationError) setError(`Asistencia guardada, pero no se pudo preparar el aviso: ${notificationError.message}`); } setBusy(""); if (markError) setError(markError.message); else { void records.reload(); if (!error) setError(""); } };
  return <><Header title="Asistencia" text="Vista en directo: se actualiza automáticamente cada 10 segundos." /><section className="panel live-attendance"><div><h2>Entrenamientos en pista ahora</h2><p>{activeSessions.length ? "Listas abiertas en este momento. El recuento cambia según se pasa lista." : "No hay ninguna lista abierta ahora mismo."}</p></div><small>Actualización automática · 10 s</small>{activeSessions.map(item => { const currentGroup = groups.find(group => group.id === item.training_group_id); const currentRoster = athletes.rows.filter(athlete => athlete.training_group_id === item.training_group_id); const present = records.rows.filter(record => record.session_id === item.id && record.attended).length; return <button className="live-session" key={item.id} onClick={() => { setGroupId(item.training_group_id); setSelectedSession(item.id); }}><span><b>{currentGroup?.name || "Grupo"}</b><small>{new Date(item.starts_at).toLocaleTimeString("es-ES", { hour: "2-digit", minute: "2-digit" })} · {present}/{currentRoster.length} presentes</small></span><span>Ver lista →</span></button>; })}</section><form className="panel inline-form" onSubmit={createSession}><label>Grupo<select required value={groupId} onChange={e => { setGroupId(e.target.value); setSelectedSession(""); }}><option value="">Selecciona un grupo</option>{groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</select></label><label>Inicio del entrenamiento<input type="datetime-local" value={when} onChange={e => setWhen(e.target.value)} /></label><button>Crear lista de hoy</button>{error && <p className="error-note">{error}</p>}</form>{groupId && <article className="panel table"><div className="row"><span><b>Sesiones del grupo</b><small>Elige una lista ya creada o crea una nueva.</small></span><select value={activeSession} onChange={e => setSelectedSession(e.target.value)}><option value="">Selecciona una sesión</option>{visibleSessions.map(s => <option key={s.id} value={s.id}>{new Date(s.starts_at).toLocaleString("es-ES")}</option>)}</select></div>{activeSession && roster.map(a => { const record = records.rows.find(r => r.session_id === activeSession && r.athlete_id === a.id); return <div className="row" key={a.id}><span><b>{a.first_name} {a.last_name}</b><small>{a.training_groups?.name}</small></span><span>{record?.attended === true ? "Asistencia confirmada" : record?.attended === false ? "No ha asistido" : "Sin marcar"}</span><span><button disabled={busy === a.id} onClick={() => void mark(a.id, true)}>Ha asistido</button> <button className="outline" disabled={busy === a.id} onClick={() => void mark(a.id, false)}>No ha asistido</button></span></div>; })}{activeSession && !roster.length && <Empty>No hay atletas asignados a este grupo.</Empty>}</article>}{!groups.length && <Empty>No tienes grupos asignados todavía.</Empty>}</>;
}
function Competitions({ manager = false }: { manager?: boolean }) { const events = useRows<{ id: string; title: string; venue: string | null; starts_at: string; internal_deadline: string | null; rules_summary: string | null }>("competition_events"); return <><Header title="Carreras y competiciones" text="Pruebas publicadas por el club y calendario oficial de la FAM."><a className="button-link" href={famCalendar} target="_blank" rel="noreferrer">Calendario FAM ↗</a></Header>{manager && <article className="panel"><h2>Circulares PDF</h2><p>La carga e interpretación se activará al conectar el almacenamiento privado. El entrenador validará siempre las categorías, pruebas y fecha interna antes de publicar.</p></article>}<div className="cards">{events.rows.map(event => <article className="panel" key={event.id}><h2>{event.title}</h2><p>{event.venue || "Ubicación pendiente"} · {new Date(event.starts_at).toLocaleString("es-ES")}</p><small>Fecha interna: {event.internal_deadline ? new Date(event.internal_deadline).toLocaleDateString("es-ES") : "por definir"}</small>{event.rules_summary && <p>{event.rules_summary}</p>}</article>)}{!events.rows.length && <Empty>No hay competiciones publicadas todavía. Consulta mientras tanto el calendario FAM.</Empty>}</div></>; }
function Announcements({ profile }: { profile: Profile }) { const notices = useRows<{ id: string; title: string; body: string; created_at: string; created_by: string }>("announcements"); const dismissed = useRows<{ announcement_id: string }>("announcement_dismissals"); const canWrite = ["owner", "admin", "coach"].includes(profile.role); const [title, setTitle] = useState(""); const [body, setBody] = useState(""); const publish = async (e: FormEvent) => { e.preventDefault(); await supabase!.from("announcements").insert({ title, body, audience: "club", created_by: profile.id, published_at: new Date().toISOString() }); setTitle(""); setBody(""); void notices.reload(); }; const dismiss = async (announcementId: string) => { if (!supabase) return; await supabase.from("announcement_dismissals").upsert({ announcement_id: announcementId, profile_id: profile.id }); void dismissed.reload(); }; useEffect(() => { if (!supabase) return; const incoming = notices.rows.filter(item => item.created_by !== profile.id && !dismissed.rows.some(hidden => hidden.announcement_id === item.id)).map(item => ({ announcement_id: item.id, profile_id: profile.id, read_at: new Date().toISOString() })); if (incoming.length) void supabase.from("announcement_reads").upsert(incoming, { onConflict: "announcement_id,profile_id" }); }, [notices.rows.length, dismissed.rows.length, profile.id]); const visible = notices.rows.filter(item => !dismissed.rows.some(hidden => hidden.announcement_id === item.id)); return <><Header title="Avisos" text="Comunicaciones del club." />{canWrite && <form className="panel stacked-form" onSubmit={publish}><label>Asunto<input required value={title} onChange={e => setTitle(e.target.value)} /></label><label>Mensaje<textarea required value={body} onChange={e => setBody(e.target.value)} /></label><button>Publicar aviso</button></form>}<div className="cards">{visible.map(n => <article className="panel" key={n.id}><h2>{n.title}</h2><p>{n.body}</p><small>{new Date(n.created_at).toLocaleString("es-ES")}</small><button className="outline" onClick={() => void dismiss(n.id)}>Quitar de mi lista</button></article>)}{!visible.length && <Empty>No hay avisos publicados.</Empty>}</div></>; }
function Member({ section, profile, go, openAthlete, focusedAthleteId }: { section: string; profile: Profile; go: (section: string) => void; openAthlete: (id: string) => void; focusedAthleteId: string }) { if (section === "Inicio" && profile.role === "parent") return <FamilyHome profile={profile} go={go} openAthlete={openAthlete} />; if (section === "Mis atletas" && profile.role === "parent") return <FamilyAthletes initialAthleteId={focusedAthleteId} />; if (section === "Carreras") return <CompetitionManager profile={profile} />; if (section === "Cuotas") return <Fees profile={profile} />; if (section === "Avisos") return <Announcements profile={profile} />; if (section === "Tienda") return <Shop profile={profile} />; const athletes = useRows<Athlete>("athletes", "*,training_groups(*)"); const mine = athletes.rows.filter(a => a.user_profile_id === profile.id); return <><Header title={section === "Mi perfil" ? "Mi perfil" : "Mis atletas"} text="Estado de alta, grupo y licencia." /><div className="cards">{mine.map(a => <article className="panel" key={a.id}><h2>{a.first_name} {a.last_name}</h2><p>{a.training_groups?.name || "Grupo pendiente de asignación"}</p><small>Estado: {a.club_status === "active" ? "Activo" : "En revisión"} · Licencia: {a.license_status === "active" ? a.license_number || "activa" : "pendiente"}</small></article>)}{!mine.length && <Empty>Tu inscripción está pendiente de revisión administrativa.</Empty>}</div></>; }
function Settings() {
  const [form, setForm] = useState({ club_name: "Club Atletas de Fuenlabrada", contact_email: "", contact_phone: "", address_line: "", season_label: "Temporada 2026/27", registration_open: false, registration_message: "", logo_url: "" }); const [logo, setLogo] = useState<File | null>(null); const [notice, setNotice] = useState(""); const [saving, setSaving] = useState(false);
  useEffect(() => { const load = async () => { if (!supabase) return; const { data, error } = await supabase.from("club_settings").select("*").eq("id", true).maybeSingle(); if (error) return setNotice(error.message); if (data) setForm({ club_name: data.club_name || "Club Atletas de Fuenlabrada", contact_email: data.contact_email || "", contact_phone: data.contact_phone || "", address_line: data.address_line || "", season_label: data.season_label || "Temporada 2026/27", registration_open: data.registration_open, registration_message: data.registration_message || "", logo_url: data.logo_url || "" }); }; void load(); }, []);
  const save = async (e: FormEvent) => { e.preventDefault(); if (!supabase) return; setSaving(true); setNotice(""); try { let logoUrl = form.logo_url || null; if (logo) { if (!logo.type.startsWith("image/")) throw new Error("Selecciona una imagen válida para el escudo."); const key = `branding/${Date.now()}-${logo.name.replace(/[^a-zA-Z0-9._-]/g, "-")}`; const { error } = await supabase.storage.from("club-assets").upload(key, logo, { contentType: logo.type }); if (error) throw error; logoUrl = supabase.storage.from("club-assets").getPublicUrl(key).data.publicUrl; } const { error } = await supabase.from("club_settings").update({ ...form, logo_url: logoUrl, updated_at: new Date().toISOString() }).eq("id", true); if (error) throw error; setForm({ ...form, logo_url: logoUrl || "" }); setLogo(null); setNotice("Configuración guardada. La identidad nueva se aplicará al recargar la aplicación."); } catch (error) { setNotice(error instanceof Error ? error.message : "No se pudo guardar la configuración."); } finally { setSaving(false); } };
  return <><Header title="Centro de configuración" text="Identidad, temporada, contacto y apertura de inscripciones del club." /><form className="settings-workspace" onSubmit={save}><article className="panel settings-brand"><div>{form.logo_url ? <img src={form.logo_url} alt="Escudo del club" /> : <b>AF</b>}</div><section><small>IDENTIDAD DEL CLUB</small><h2>{form.club_name}</h2><label>Escudo o logotipo<input type="file" accept="image/*" onChange={e => setLogo(e.target.files?.[0] || null)} /></label><small>{logo ? logo.name : "PNG, JPG o WEBP. El archivo se guarda en el almacenamiento privado del club."}</small></section></article><article className="panel"><h2>Datos visibles del club</h2><div className="ops-grid"><label>Nombre del club<input required value={form.club_name} onChange={e => setForm({ ...form, club_name: e.target.value })} /></label><label>Temporada activa<input required value={form.season_label} onChange={e => setForm({ ...form, season_label: e.target.value })} /></label><label>Email de contacto<input type="email" value={form.contact_email} onChange={e => setForm({ ...form, contact_email: e.target.value })} placeholder="info@club…" /></label><label>Teléfono de contacto<input value={form.contact_phone} onChange={e => setForm({ ...form, contact_phone: e.target.value })} /></label><label>Dirección o instalación<input value={form.address_line} onChange={e => setForm({ ...form, address_line: e.target.value })} placeholder="Estadio Raúl González, URJC" /></label></div></article><article className="panel"><h2>Inscripciones</h2><label className="check-line"><input type="checkbox" checked={form.registration_open} onChange={e => setForm({ ...form, registration_open: e.target.checked })} />Permitir nuevas inscripciones desde la página pública</label><label>Mensaje para familias<textarea value={form.registration_message} onChange={e => setForm({ ...form, registration_message: e.target.value })} placeholder="Las altas se revisan antes de quedar activas." /></label></article><article className="panel settings-status"><h2>Operativa y seguridad</h2><p><b>Pagos:</b> Stripe/TPV se configura con claves seguras en Cloudflare; nunca en esta pantalla.</p><p><b>Equipo:</b> los administradores y entrenadores se gestionan desde Invitaciones y Grupos.</p><p><b>Normativas:</b> se muestran dentro de la inscripción antes de que la familia las acepte.</p></article><button disabled={saving}>{saving ? "Guardando…" : "Guardar configuración del club"}</button>{notice && <p className={notice.startsWith("Configuración") ? "success-note panel" : "error-note panel"}>{notice}</p>}</form></>;
}

